import assert from 'node:assert/strict';
import { ToyRoomPhase } from '../src/js/toy-room/ToyRoomPhase.js';
import { ToyRoomStory } from '../src/js/toy-room/ToyRoomStory.js';
for (const [width,height] of [[390,844],[844,390],[960,540]]) {
 const room=Object.create(ToyRoomPhase.prototype);
 Object.assign(room,{canvas:{width,height},ROOM_W:1600,ROOM_H:1200,mobilePresentation:true,
 player:{x:800,y:600},fairy:{x:120,y:200},cameraX:250,cameraY:250});
 room.story=Object.create(ToyRoomStory.prototype);room.story.room=room;
 room.story.state={investigationStage:'COLLECTING',investigationElapsed:0,sword:{x:1400,y:950,visible:true}};
 for (const stage of ['COLLECTING','SEEKING_SWORD','PICKUP','EQUIPPED','INVESTIGATION']) {
  room.story.state.investigationStage=stage;
  for (const elapsed of [0,180,480,840,959,1260,1500,1829]) {
   room.story.state.investigationElapsed=elapsed;
   assert.equal(room.story.cameraTarget(),room.player,'Foco na menina fora da revelação');
   const frame=room.getCameraFrame();room.cameraX=250;room.cameraY=250;room.updateCamera(1);
   const camera=[room.cameraX,room.cameraY];room.cameraX=250;room.cameraY=250;
   room.fairy.x=1500;room.fairy.y=1100;
   assert.deepEqual(room.getCameraFrame(),frame,'Fada distante não muda escala nem translação');
   room.updateCamera(1);assert.deepEqual([room.cameraX,room.cameraY],camera,'Fada não muda câmera lógica');
   room.cameraX=250;room.cameraY=250;room.fairy.x=120;room.fairy.y=200;
  }
 }
 room.story.state.investigationStage='INVESTIGATION';room.story.state.investigationElapsed=960;
 assert.equal(room.story.cameraTarget(),room.fairy,'Revelação acompanha a fada');
 const reveal=room.getCameraFrame();room.fairy.x=1400;room.fairy.y=950;
 assert.notDeepEqual(room.getCameraFrame(),reveal,'Foco temporário acompanha o deslocamento da fada');
 room.story.state.investigationElapsed=1260;
 assert.equal(room.story.cameraTarget(),room.player,'Retorno imediato do alvo após revelação');
 room.cameraX=250;room.cameraY=250;room.updateCamera(1);const once=[room.cameraX,room.cameraY];
 room.cameraX=250;room.cameraY=250;room.updateCamera(.5);room.updateCamera(.5);
 for(let i=0;i<2;i++)assert.ok(Math.abs([room.cameraX,room.cameraY][i]-once[i])<1e-9,'Suavização independente do passo de atualização');
}
console.log('APROVADO: câmera e zoom independentes da fada em três perfis; revelação temporária, retorno à menina e suavização estável.');
